class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        if not isinstance(word, str) or len(word) == 0:
            raise ValueError("Word must be a non-empty string")
        curr = self.root
        for char in word:
            if char not in curr.children:
                curr.children[char] = TrieNode()
            curr = curr.children[char]
        curr.is_end_of_word = True

    def search(self, word: str) -> bool:
        if not isinstance(word, str) or len(word) == 0:
            return False
        curr = self.root
        for char in word:
            if char not in curr.children:
                return False
            curr = curr.children[char]
        return curr.is_end_of_word

    def starts_with(self, prefix: str) -> bool:
        if not isinstance(prefix, str):
            raise TypeError("Prefix must be a string")
        if len(prefix) == 0:
            return True
        curr = self.root
        for char in prefix:
            if char not in curr.children:
                return False
            curr = curr.children[char]
        return True

    def delete(self, word: str) -> bool:
        if not isinstance(word, str) or len(word) == 0:
            return False

        def _delete_helper(curr, w, depth):
            if depth == len(w):
                if not curr.is_end_of_word:
                    return False
                curr.is_end_of_word = False
                return len(curr.children) == 0
            char = w[depth]
            if char not in curr.children:
                return False
            should_delete_child = _delete_helper(curr.children[char], w, depth + 1)
            if should_delete_child:
                del curr.children[char]
                return len(curr.children) == 0 and not curr.is_end_of_word
            return False

        if not self.search(word):
            return False
        _delete_helper(self.root, word, 0)
        return True

class MinHeap:
    def __init__(self):
        self._heap = []

    def __len__(self) -> int:
        return len(self._heap)

    def peek(self):
        if not self._heap:
            raise IndexError("peek from empty heap")
        return self._heap[0]

    def push(self, val):
        if not isinstance(val, (int, float)):
            raise TypeError("Heap elements must be numeric")
        self._heap.append(val)
        self._sift_up(len(self._heap) - 1)

    def pop_min(self):
        if not self._heap:
            raise IndexError("pop from empty heap")
        if len(self._heap) == 1:
            return self._heap.pop()
        min_val = self._heap[0]
        self._heap[0] = self._heap.pop()
        self._sift_down(0)
        return min_val

    def _sift_up(self, idx):
        parent = (idx - 1) // 2
        while idx > 0 and self._heap[idx] < self._heap[parent]:
            self._heap[idx], self._heap[parent] = self._heap[parent], self._heap[idx]
            idx = parent
            parent = (idx - 1) // 2

    def _sift_down(self, idx):
        n = len(self._heap)
        while True:
            smallest = idx
            left = 2 * idx + 1
            right = 2 * idx + 2
            if left < n and self._heap[left] < self._heap[smallest]:
                smallest = left
            if right < n and self._heap[right] < self._heap[smallest]:
                smallest = right
            if smallest != idx:
                self._heap[idx], self._heap[smallest] = self._heap[smallest], self._heap[idx]
                idx = smallest
            else:
                break

import heapq

class MedianFinder:
    def __init__(self):
        self.small = []  # max-heap (invertido)
        self.large = []  # min-heap

    def add_num(self, num: int | float) -> None:
        if not isinstance(num, (int, float)):
            raise TypeError("Number must be an int or float")
        heapq.heappush(self.small, -num)

        # Asegurar que todo elemento en small <= todo elemento en large
        if self.small and self.large and (-self.small[0] > self.large[0]):
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)

        # Balance de tamano: len(small) == len(large) o len(small) == len(large) + 1
        if len(self.small) > len(self.large) + 1:
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        elif len(self.large) > len(self.small):
            val = heapq.heappop(self.large)
            heapq.heappush(self.small, -val)

    def find_median(self) -> float:
        if not self.small and not self.large:
            raise ValueError("No numbers in stream")
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return float((-self.small[0] + self.large[0]) / 2.0)

def rotate_matrix_90_clockwise(matrix: list[list[int]]) -> None:
    if not isinstance(matrix, list):
        raise TypeError("Matrix must be a list")
    if not matrix:
        return
    n = len(matrix)
    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("Rows must be lists")
        if len(row) != n:
            raise ValueError("Matrix must be square")
        for val in row:
            if not isinstance(val, (int, float)):
                raise TypeError("Elements must be numbers")

    # Transposicion
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Inversion de cada fila
    for i in range(n):
        matrix[i].reverse()

def intersect_interval_lists(first_list: list[list[int]], second_list: list[list[int]]) -> list[list[int]]:
    if not isinstance(first_list, list) or not isinstance(second_list, list):
        raise TypeError("Inputs must be lists")

    def _validate(lst):
        for item in lst:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError("Interval must be a 2-element sequence")
            s, e = item
            if not isinstance(s, int) or not isinstance(e, int):
                raise TypeError("Interval bounds must be integers")
            if s > e:
                raise ValueError(f"Invalid interval: start {s} > end {e}")

    _validate(first_list)
    _validate(second_list)

    i, j = 0, 0
    res = []
    while i < len(first_list) and j < len(second_list):
        s1, e1 = first_list[i]
        s2, e2 = second_list[j]

        start = max(s1, s2)
        end = min(e1, e2)

        if start <= end:
            res.append([start, end])

        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

