import re

def rle_encode(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        return ""
    res = []
    curr_char = text[0]
    count = 1
    for char in text[1:]:
        if char == curr_char:
            count += 1
        else:
            res.append(f"{curr_char}{count}")
            curr_char = char
            count = 1
    res.append(f"{curr_char}{count}")
    return "".join(res)

def rle_decode(encoded: str) -> str:
    if not isinstance(encoded, str):
        raise TypeError("encoded must be a string")
    if not encoded:
        return ""
    # Formato estricto: pares (caracter no digito)(uno o mas digitos)
    pattern = re.compile(r"^([^0-9]\d+)+$")
    if not pattern.match(encoded):
        raise ValueError("Invalid RLE encoded format")
    tokens = re.findall(r"([^0-9])(\d+)", encoded)
    res = []
    for char, count_str in tokens:
        count = int(count_str)
        if count <= 0:
            raise ValueError("Count must be positive")
        res.append(char * count)
    return "".join(res)

import itertools

def batch_stream(iterable, batch_size: int):
    if not isinstance(batch_size, int) or batch_size <= 0:
        raise ValueError("batch_size must be an integer greater than 0")

    it = iter(iterable)
    while True:
        batch = list(itertools.islice(it, batch_size))
        if not batch:
            break
        yield batch

