def search_rotated_sorted_array(nums: list[int], target: int) -> int:
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    if not isinstance(target, int):
        raise TypeError("target must be an integer")
    if not nums:
        return -1
    for x in nums:
        if not isinstance(x, int):
            raise TypeError("All elements must be integers")

    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Mitad izquierda ordenada
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Mitad derecha ordenada
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def detect_cycle_start(head: ListNode | None) -> ListNode | None:
    if head is None:
        return None
    if not isinstance(head, ListNode):
        raise TypeError("head must be a ListNode or None")

    slow = head
    fast = head

    # Fase 1: Encontrar punto de encuentro
    has_cycle = False
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            has_cycle = True
            break

    if not has_cycle:
        return None

    # Fase 2: Encontrar el nodo de inicio del ciclo
    ptr1 = head
    ptr2 = slow
    while ptr1 is not ptr2:
        ptr1 = ptr1.next
        ptr2 = ptr2.next

    return ptr1

class EventEmitter:
    def __init__(self):
        self._events = {}

    def on(self, event: str, listener):
        if not callable(listener):
            raise TypeError("Listener must be callable")
        if event not in self._events:
            self._events[event] = []
        self._events[event].append(listener)

        unsubscribed = False
        def unsubscribe():
            nonlocal unsubscribed
            if not unsubscribed:
                unsubscribed = True
                self.remove_listener(event, listener)
        return unsubscribe

    def once(self, event: str, listener):
        if not callable(listener):
            raise TypeError("Listener must be callable")
        def wrapper(*args, **kwargs):
            self.remove_listener(event, wrapper)
            return listener(*args, **kwargs)
        self.on(event, wrapper)

    def remove_listener(self, event: str, listener) -> bool:
        if event in self._events and listener in self._events[event]:
            self._events[event].remove(listener)
            return True
        return False

    def emit(self, event: str, *args, **kwargs) -> int:
        if event not in self._events or not self._events[event]:
            return 0
        listeners = list(self._events[event])
        count = 0
        for l in listeners:
            l(*args, **kwargs)
            count += 1
        return count

class DisjointSetUnion:
    def __init__(self, n: int):
        if not isinstance(n, int) or n <= 0:
            raise ValueError("n must be a positive integer")
        self.n = n
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x: int) -> int:
        if not isinstance(x, int) or x < 0 or x >= self.n:
            raise IndexError("Index out of bounds")
        root = x
        while root != self.parent[root]:
            root = self.parent[root]
        # Compresion de camino
        curr = x
        while curr != root:
            nxt = self.parent[curr]
            self.parent[curr] = root
            curr = nxt
        return root

    def union(self, x: int, y: int) -> bool:
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return False

        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1

        self.components -= 1
        return True

    def count_components(self) -> int:
        return self.components

def next_greater_elements(nums: list[int]) -> list[int]:
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    for x in nums:
        if not isinstance(x, int):
            raise TypeError("All elements must be integers")
    if not nums:
        return []

    n = len(nums)
    res = [-1] * n
    stack = []  # indices con valores decrecientes

    for i in range(n):
        while stack and nums[i] > nums[stack[-1]]:
            idx = stack.pop()
            res[idx] = nums[i]
        stack.append(i)

    return res

