import re

def roman_to_int(roman: str) -> int:
    if not isinstance(roman, str):
        raise TypeError("roman must be a string")
    if not roman:
        raise ValueError("roman string cannot be empty")

    # Expresion regular canónica para números romanos estándar (1 a 3999)
    valid_roman_pattern = re.compile(
        r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
    )
    if not valid_roman_pattern.match(roman):
        raise ValueError(f"Invalid Roman numeral: '{roman}'")

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    n = len(roman)
    for i in range(n):
        curr_val = values[roman[i]]
        if i + 1 < n and curr_val < values[roman[i + 1]]:
            total -= curr_val
        else:
            total += curr_val
    return total

def is_ip_in_cidr(ip: str, cidr: str) -> bool:
    if not isinstance(ip, str) or not isinstance(cidr, str):
        raise TypeError("ip and cidr must be strings")

    def _parse_ipv4(addr_str: str) -> int:
        parts = addr_str.split('.')
        if len(parts) != 4:
            raise ValueError(f"Invalid IPv4: {addr_str}")
        num = 0
        for part in parts:
            if not part.isdigit():
                raise ValueError(f"Invalid octet: '{part}'")
            if len(part) > 1 and part.startswith('0'):
                raise ValueError(f"Leading zeros not allowed: '{part}'")
            val = int(part)
            if val < 0 or val > 255:
                raise ValueError(f"Octet out of range: {val}")
            num = (num << 8) | val
        return num

    if '/' not in cidr:
        raise ValueError("CIDR must contain '/'")
    network_str, prefix_str = cidr.split('/', 1)
    if not prefix_str.isdigit():
        raise ValueError("CIDR prefix must be integer")
    prefix = int(prefix_str)
    if prefix < 0 or prefix > 32:
        raise ValueError("CIDR prefix must be between 0 and 32")

    ip_int = _parse_ipv4(ip)
    net_int = _parse_ipv4(network_str)

    if prefix == 0:
        return True
    mask = ((1 << 32) - 1) ^ ((1 << (32 - prefix)) - 1)
    return (ip_int & mask) == (net_int & mask)

