import threading
import time
from collections import deque

class BoundedBlockingQueue:
    def __init__(self, capacity: int):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self.queue = deque()
        self.lock = threading.Lock()
        self.not_empty = threading.Condition(self.lock)
        self.not_full = threading.Condition(self.lock)

    def qsize(self) -> int:
        with self.lock:
            return len(self.queue)

    def put(self, item, timeout: float = None) -> bool:
        start_time = time.time()
        with self.not_full:
            while len(self.queue) >= self.capacity:
                if timeout is not None:
                    elapsed = time.time() - start_time
                    remaining = timeout - elapsed
                    if remaining <= 0:
                        return False
                    if not self.not_full.wait(remaining):
                        return False
                else:
                    self.not_full.wait()
            self.queue.append(item)
            self.not_empty.notify()
            return True

    def get(self, timeout: float = None):
        start_time = time.time()
        with self.not_empty:
            while not self.queue:
                if timeout is not None:
                    elapsed = time.time() - start_time
                    remaining = timeout - elapsed
                    if remaining <= 0:
                        raise TimeoutError("Queue get timed out")
                    if not self.not_empty.wait(remaining):
                        raise TimeoutError("Queue get timed out")
                else:
                    self.not_empty.wait()
            item = self.queue.popleft()
            self.not_full.notify()
            return item

class IllegalStateTransitionError(Exception):
    pass

class OrderStateMachine:
    VALID_STATES = {'created', 'paid', 'shipped', 'delivered', 'cancelled'}
    TRANSITIONS = {
        ('created', 'pay'): 'paid',
        ('created', 'cancel'): 'cancelled',
        ('paid', 'ship'): 'shipped',
        ('paid', 'cancel'): 'cancelled',
        ('shipped', 'deliver'): 'delivered',
    }

    def __init__(self, initial_state: str = 'created'):
        if initial_state not in self.VALID_STATES:
            raise ValueError(f"Invalid initial state: '{initial_state}'")
        self._state = initial_state

    @property
    def current_state(self) -> str:
        return self._state

    def transition(self, event: str) -> str:
        key = (self._state, event)
        if key not in self.TRANSITIONS:
            raise IllegalStateTransitionError(
                f"Cannot perform event '{event}' from state '{self._state}'"
            )
        self._state = self.TRANSITIONS[key]
        return self._state

def apply_discount_rules(order: dict) -> dict:
    if not isinstance(order, dict):
        raise TypeError("order must be a dictionary")

    subtotal = order.get("items_subtotal")
    if subtotal is None or not isinstance(subtotal, (int, float)) or subtotal < 0:
        raise ValueError("items_subtotal must be a non-negative number")

    tier = order.get("user_tier", "standard")
    tier_discounts = {
        "standard": 0.0,
        "gold": 0.10,
        "vip": 0.20
    }
    if tier not in tier_discounts:
        raise ValueError(f"Unknown user_tier: '{tier}'")

    # 1. Tier discount
    tier_discount_amount = subtotal * tier_discounts[tier]
    price_after_tier = subtotal - tier_discount_amount

    # 2. Coupon discount
    coupon = order.get("coupon_code", "")
    coupon_discount_amount = 0.0
    if coupon == "SAVE10":
        coupon_discount_amount = 10.0
    elif coupon == "SAVE20":
        coupon_discount_amount = 20.0

    # Tope de cupon: maximo 50% de price_after_tier
    max_coupon_discount = price_after_tier * 0.50
    effective_coupon_discount = min(coupon_discount_amount, max_coupon_discount)

    total_discount = tier_discount_amount + effective_coupon_discount
    final_price = max(0.0, round(subtotal - total_discount, 2))

    return {
        "final_price": final_price,
        "discount_applied": round(total_discount, 2)
    }
